Given an array of n integers, find the sum of XOR of all pairs of numbers in the array.Examples:Input: arr[] = [7, 3, 5]Output: 12Explanation:All possible pairs and there XORValue: (7 ^ 3 = 4) + (3 ^ 5 = 6)(7 ^ 5 = 2) = 4 + 6 + 2  = 12Input: arr[] = [5, 9, 7, 6]Output: 47Explanation:All possible pairs and there XORValue: (5 ^ 9 = 12) + (5 ^ 7 = 2) + (5 ^ 6 = 3) + (9 ^ 7 = 14) + (9 ^ 6 = 15) + (7 ^ 6 = 1) = 12 + 2 + 3 + 14 + 15 + 1 = 47Try It YourselfTable of Content[Naive Approach] Iterative Method - O(n^2) Time and O(1) Space[Expected Approach] Bit Manipulation - O(n) Time and O(1) Space[Naive Approach] Iterative Method - O(n^2) Time and O(1) SpaceIterate over all unique pairs of elements and compute their XOR, adding each result to the total sum. Dry run for arr[] = [7, 3, 5]:Initial sum = 0i = 0 (7)j = 1: 7 ^ 3 = 4 then add to sum, now sum = 4j = 2: 7 ^ 5 = 2 then add to sum, now sum = 6i = 1 (3)j = 2: 3 ^ 5 = 6 then add to sum, now sum = 12All unique pairs are processed, Final sum = 12
            C++

    #include <iostream>
#include <vector>
using namespace std;

long sumXOR(vector<int> arr)
{
    long sum = 0;

    // Consider all pairs (arr[i], arr[j) such that
    // i < j
    for (int i = 0; i < arr.size() - 1; i++)
        for (int j = i + 1; j < arr.size(); j++)
            sum += arr[i] ^ arr[j];

    return sum;
}

int main()
{
    vector<int> arr = { 5, 9, 7, 6 };

    cout << sumXOR(arr);
    return 0;
}


